#!/usr/bin/env node
// Builds lib/prompts.generated.js from prompts/*.md + prompts/modes.json.
// Prompts ship as a plain JS module so Vercel's bundler traces them (no runtime fs reads).
// Usage: node scripts/build-prompts.mjs [--check]   (--check exits 1 if the generated file is stale)
import { readFileSync, writeFileSync } from "node:fs";

const dir = new URL("../prompts/", import.meta.url);
const out = new URL("../lib/prompts.generated.js", import.meta.url);
const manifest = JSON.parse(readFileSync(new URL("modes.json", dir), "utf8"));
const read = (name) =>
  readFileSync(new URL(`${name}.md`, dir), "utf8")
    .replace(/\r\n/g, "\n")
    .replace(/<!--[\s\S]*?-->\s*/g, "") // comments are for humans; don't pay tokens for them
    .trim();

const prompts = {};
for (const [mode, cfg] of Object.entries(manifest)) {
  if (mode.startsWith("_")) continue;
  prompts[mode] = cfg.parts.map(read).join("\n\n");
}

const src =
  "// GENERATED by scripts/build-prompts.mjs from prompts/*.md. Do not edit; run `npm run build:prompts`.\n" +
  `module.exports = ${JSON.stringify(prompts, null, 2)};\n`;

if (process.argv.includes("--check")) {
  let current = "";
  try { current = readFileSync(out, "utf8").replace(/\r\n/g, "\n"); } catch {}
  if (current !== src) {
    console.error("lib/prompts.generated.js is stale. Run: npm run build:prompts");
    process.exit(1);
  }
  console.log("prompts in sync.");
} else {
  writeFileSync(out, src);
  console.log(`Wrote ${Object.keys(prompts).length} prompts to lib/prompts.generated.js`);
}
